import React ,{useState}from "react";
import Meals from "./Meals";
import Cart from "./Cart";
const HomePage=()=>{
   // const [cartAmount, setCartAmount] = useState(0);
    const [cartItems, setCartItems] = useState([]);

  // const updateCartAmount = (item) => {
  //   setCartAmount(cartAmount + (item.amount));
  // };

  const updateCartItems = (item) => {
    const existingItemIndex = cartItems.findIndex((i) => i.id === item.id);

    if (existingItemIndex !== -1) {
        const updatedItems = [...cartItems];
        updatedItems[existingItemIndex].amount += item.amount;
        setCartItems(updatedItems);
    } else {
        setCartItems((prevItems) => [...prevItems, { ...item }]);
    }
};
  const updateCartAmount = (item) => {
    setCartItems([...cartItems, item]); // Add the new item to the cartItems array
  };
    return(
        <div>
           <div><h1> these are meals</h1></div>
           <Meals addToCart={updateCartAmount}></Meals>
           <Cart items={cartItems}></Cart>
        </div>
    )
}
export default HomePage;
